import { navigate } from "gatsby";
import React from "react";
import { AdminLayout } from "../../features/admin/components/AdminLayout";
import { useAuth } from "../../features/auth/AuthContext";

export default function AdminDashboard() {
  const { user } = useAuth();

  return (
    <AdminLayout title="Dashboard">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <DashboardCard
          label="Users"
          description="Manage customers and agents."
          onClick={() => navigate("/admin/users")}
        />
        <DashboardCard
          label="Itineraries"
          description="Create and manage travel itineraries."
          onClick={() => navigate("/admin/itineraries")}
        />
        <DashboardCard
          label="Support notes"
          description="Internal follow-up notes."
          onClick={() => navigate("/admin/support")}
        />
        <DashboardCard
          label="Audit log"
          description="Track all changes in the system."
          onClick={() => navigate("/admin/audit")}
        />
      </div>
      <p className="mt-8 text-xs text-gray-400">
        Signed in as {user?.email}
      </p>
    </AdminLayout>
  );
}

function DashboardCard({
  label,
  description,
  onClick,
}: {
  label: string;
  description: string;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="rounded-xl bg-white p-5 text-left shadow-sm ring-1 ring-gray-200 transition hover:ring-gray-400"
    >
      <p className="font-semibold text-gray-900">{label}</p>
      <p className="mt-1 text-sm text-gray-500">{description}</p>
    </button>
  );
}
